contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 probe) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (probe)); require(amount <= 1000000000000000000000000000000); require(probe <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // Observe the caller's credit indirectly: deposit a tiny probe amount and
        // see how much the contract's Ether balance increases.
        uint256 balBefore = address(c).balance;
        c.deposit{value: probe}(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;
        uint256 depositIncrease = balAfter - balBefore; // equals probe always, but credit is
        // not directly observable; we can infer credit by comparing real balance change.

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: after a withdrawAll, the contract's Ether balance decreases by
        // exactly the total amount that msg.sender had deposited (amount + probe), and
        // the caller's credit is cleared. If withdrawAll reverts, the balance is unchanged.
        uint256 expectedDecrease = amount + probe;
        uint256 finalBalance = address(c).balance;
        assert(
            (reverted && finalBalance == balBefore + probe) ||
            (!reverted && finalBalance == balBefore + probe - expectedDecrease)
        );
    }

    receive() external payable {}
}

