pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount, uint256 probe) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        probe = bound(probe, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.deposit{value: amount}() {} catch { return; }
        uint256 balBefore = address(c).balance;
        try c.deposit{value: probe}() {} catch { return; }
        uint256 balAfter = address(c).balance;
        uint256 depositIncrease = balAfter - balBefore;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 expectedDecrease = amount + probe;
        uint256 finalBalance = address(c).balance;
        assertTrue((reverted && finalBalance == balBefore + probe) ||
            (!reverted && finalBalance == balBefore + probe - expectedDecrease));
    }

    function testFuzz_run(uint256 amount, uint256 probe) public {
        _run(amount, probe);
    }

    receive() external payable {}
}
